('excel-2024', 'EXCEL 2024 Conference', 'Nov 15–17, 2024', '2024-11-15', '2024-11-17', '2024-11-15 09:00:00', '2024-11-17 17:00:00', 'Africa/Accra', 'Accra, Ghana', NULL, 'assets/image/hero/001-w800.jpg', 'INSPIRED • INTENTIONAL • INTENSE - Our annual conference designed to inspire and equip young Christian professionals with foresight and insight. Three days of transformative learning, worship, and networking with 100+ Christian professionals.', '', '1', '2026-05-25 21:30:27', '2026-05-25 21:30:27'),
('regional-workshop-kumasi', 'Regional Practitioner Workshop', '2026-01-20', '2026-01-20', '2026-01-20', '2026-01-20 09:00:00', '2026-01-20 16:00:00', 'Africa/Accra', 'Kumasi', 'gad', 'assets/image/002.jpg', 'Hands-on workshops focused on pedagogy, governance toolkits and ethical decision-making for mid-career professionals.', 'https://example.com/register/regional-workshop-kumasi', '0', '2026-05-25 21:30:27', '2026-05-26 09:41:14'),
