INSERT INTO `news` (`id`, `title`, `published_at`, `author`, `excerpt`, `featured_image`, `faculty_id`, `content`, `created_at`, `updated_at`) VALUES 
('cce-launches-policy-brief', 'CCE publishes new policy brief on ethical governance', '2025-09-01', 'Dr. A. Example', 'A concise policy brief exploring ethics in public administration and practical reforms for institutional resilience.', 'assets/image/001.jpg', 'gad', '<p>The Cross-Cutting Excellence team today released a policy brief examining the ethical foundations of governance and recommending actionable reforms for institutions. The brief synthesizes best practices from practitioner-led research and field interventions, focusing on transparency, accountability, and capacity-building.</p><p>Key recommendations include stronger procurement oversight, professional development for middle managers, and measurement frameworks tied to ethical outcomes. Download the full brief from our resources page or contact the policy team for collaboration.</p>', '2026-05-25 21:30:27', '2026-05-26 10:04:48'),
('training-recap-july', 'Training recap: governance toolkit workshop', '2025-07-05', 'Faculty Team', 'A recap of our governance toolkit workshop with materials and recordings for participants.', 'assets/image/003.jpg', NULL, '<p>In July we ran a three-day governance toolkit workshop attended by 60 mid-career professionals. Sessions covered diagnostic assessments, stakeholder mapping, and ethics in procurement. Materials and session recordings are available for registered participants.</p><p>Contact the Faculty Team to request access to slides and datasets for your organisation.</p>', '2026-05-25 21:30:27', '2026-05-25 21:30:27'),
('volunteer-spotlight-sep', 'Volunteer spotlight: mentorship in action', '2025-08-18', 'CCE Communications', 'Highlighting the impact of volunteer mentors working with early-career professionals across our faculties.', 'assets/image/002.jpg', NULL, '<p>Our volunteers are the backbone of CCE’s mentorship programs. This month we visited mentorship cohorts in Accra and Kumasi to hear stories of transformation—professionals receiving coaching, applying governance toolkits, and launching community projects.</p><p>Read testimony from mentors and mentees and see recommended materials for facilitators.</p>', '2026-05-25 21:30:27', '2026-05-25 21:30:27');

